#!/usr/bin/env python3
"""Create audiobook from Paul Graham essays."""

import os
import re
import subprocess
import requests
import sys

# --- Helper Functions ---

def fetch_article_content(url):
    """Fetch article content using curl for reliability."""
    print(f"Fetching: {url}")
    # Use curl to get raw HTML - more reliable than web fetch tools
    try:
        result = subprocess.run(
            ["curl", "-s", "-L", url], # Added -L to follow redirects
            capture_output=True,
            text=True,
            check=True
        )
        html = result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error fetching {url}: {e}")
        return ""

    # Basic HTML cleaning for Paul Graham's site (which is very simple HTML)
    # We want to extract the main content. PG's site usually puts content in <font face="verdana"> or similar.
    # But let's try a general approach first, then refine if needed.

    # Remove script and style tags
    text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL | re.IGNORECASE)

    # PG's essays are often just text with <br> tags. Replace <br> with newlines.
    text = re.sub(r'<br\s*/?>', '\n', text, flags=re.IGNORECASE)
    text = re.sub(r'<p[^>]*>', '\n\n', text, flags=re.IGNORECASE)

    # Remove all other tags
    text = re.sub(r'<[^>]+>', ' ', text)

    # Decode HTML entities
    import html as html_lib
    text = html_lib.unescape(text)

    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text).strip()

    # Specific cleanup for PG's site footer/header noise if possible, 
    # but the generic cleaning might be enough.
    # PG's essays often end with notes. We'll keep them.

    return text

def verify_content(text, expected_min_chars=1000):
    """Basic verification that content is complete."""
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    return True

def clean_text_for_tts(text):
    """Clean text for better TTS output."""
    # Remove URLs
    text = re.sub(r'http[s]?://\S+', ' ', text)

    # Remove footnote markers like [1], [2]
    text = re.sub(r'\[\d+\]', ' ', text)

    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text)

    # Remove special characters that confuse TTS but keep sentence structure
    # text = re.sub(r'[^\w\s.,!?;:\'"()-]', '', text) 
    # (Relaxed this a bit to allow for some punctuation variety)

    return text.strip()

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    # Split by common sentence endings
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""

    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk.strip())

    return chunks

# --- TTS Providers ---

def create_audiobook(text, output_path):
    """Convert text to audiobook with automatic TTS provider selection."""

    # Check available providers
    has_elevenlabs = bool(os.environ.get("ELEVENLABS_API_KEY"))
    has_openai = bool(os.environ.get("OPENAI_API_KEY"))

    if has_elevenlabs:
        print("Using ElevenLabs TTS (highest quality)")
        return create_with_elevenlabs(text, output_path)
    elif has_openai:
        print("Using OpenAI TTS (high quality)")
        return create_with_openai(text, output_path)
    else:
        print("Using gTTS (free, no API key required)")
        return create_with_gtts(text, output_path)

def create_with_elevenlabs(text, output_path):
    """Generate audiobook using ElevenLabs API."""
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                # Don't fail immediately, try to continue or return partial?
                # For now, let's return False to indicate failure.
                return False
        except Exception as e:
            print(f"Exception during ElevenLabs request: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    """Generate audiobook using OpenAI TTS API."""
    api_key = os.environ.get("OPENAI_API_KEY")

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx", 
                    "response_format": "mp3"
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception during OpenAI request: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    """Generate audiobook using gTTS (free, no API key)."""
    try:
        from gtts import gTTS
    except ImportError:
        print("gTTS not installed. Installing...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "gTTS"])
        from gtts import gTTS

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    for i, chunk in enumerate(chunks):
        chunk_file = f"/root/.gemini/tmp/chunk_{i:03d}.mp3"
        print(f"Processing chunk {i+1}/{len(chunks)}...")

        try:
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"Error with gTTS: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def concatenate_audio(audio_files, output_path):
    """Concatenate multiple audio files using ffmpeg."""
    if not audio_files:
        return False

    # Create file list for ffmpeg
    list_file = "/root/.gemini/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            f.write(f"file '{audio_file}'\n")

    print("Concatenating audio files...")
    # Concatenate with ffmpeg
    try:
        result = subprocess.run([
            "ffmpeg", "-y", "-f", "concat", "-safe", "0",
            "-i", list_file, "-c", "copy", output_path
        ], capture_output=True, check=True)
    except subprocess.CalledProcessError as e:
        print(f"FFmpeg failed: {e.stderr.decode()}")
        return False

    # Cleanup temp files
    for f in audio_files:
        try:
            os.unlink(f)
        except OSError:
            pass
    try:
        os.unlink(list_file)
    except OSError:
        pass

    return True

# --- Main ---

def main():
    # Fetch articles
    urls = [
        "http://paulgraham.com/ds.html",
        "http://paulgraham.com/foundermode.html"
    ]

    all_text = ""
    for url in urls:
        text = fetch_article_content(url)

        # PG's pages often have the title in <title> or <h1>/<img> at top.
        # We might want to add a spoken title.
        title = "Unknown Title"
        if "ds.html" in url:
            title = "Do Things that Don't Scale"
        elif "foundermode.html" in url:
            title = "Founder Mode"

        # Add title to text
        text_with_intro = f"Essay: {title}. \n\n {text}"

        if not verify_content(text):
            print(f"WARNING: Content from {url} may be incomplete or empty.")
            # Continue anyway? Or skip? Let's verify if we got anything useful.
            if len(text) < 100:
                 print("Skipping due to lack of content.")
                 continue

        all_text += f"\n\n{text_with_intro}"
        print(f"Fetched {len(text)} characters from {url}")

    if not all_text.strip():
        print("No content fetched. Exiting.")
        return

    # Clean and convert
    clean_text = clean_text_for_tts(all_text)
    print(f"Total clean text: {len(clean_text)} characters")

    # Create audiobook
    success = create_audiobook(clean_text, "/root/audiobook.mp3")

    if success:
        print(f"Audiobook created successfully at /root/audiobook.mp3")
    else:
        print("Failed to create audiobook")

if __name__ == "__main__":
    main()

